// A Mac of today around the scene it wraps: a menu bar across the top, the scene
// in a window, and the Dock below. The mark and the status icons with the clock
// open the frame's page (a Mac restarts from the mark's menu), Scenes and the
// Dock's grid the scene list, Settings and the Dock's gear the scene's settings.
// The traffic lights: red closes the scene to the list, yellow puts the window
// away and green takes its frame off; the scene's icon in the Dock, or Window,
// brings either back. Built-in scenes are drawn in the window too.
//
// On a frame that runs its scenes side by side (a Raspberry Pi: app.frame.scenes
// is there), it is a desktop: every scene opened is a window, and they all run at
// once, and chosen in another desktop's place (the frame page's Layout), it opens what
// that one had open. A window opens at the layout's "Window size" (800x480, a 7.5-inch frame's,
// unless it says otherwise), filling the desktop where that does not fit, and
// where it was when its scene opens again. The scene with the focus is the
// frame's own (the <yield />), the others are <Scene>s. Drag a title bar to move a
// window and an edge to size it, double click it (or the green light) to zoom it
// to the desktop, let it go at the top edge to fill it or at a side to take that
// half; yellow puts it away and red closes it. The Dock has the frame's scenes, a
// dot under the ones open (a click opens one or brings it back), and Launchpad
// (the scene list), the scene store and the asset browser where the frame has
// them (the mark's menu has the store too), System Settings (the frame's page) and
// Terminal. The menu bar
// names the window in front: Scenes opens a scene, Settings the settings of the
// scene in front, Window lists the windows open, and F11 or Window's "Enter Full
// Screen" gives the panel to the window in front (Escape takes it back, and the
// pointer at the top edge brings the menu bar). Alt+Tab goes between windows,
// Alt+F4 closes the one in front. The gear at the right of a scene's title bar
// opens its settings ("Clock Settings", a window a scene, several open at once);
// the frame's own scenes open in windows of their own over the scene, stay open
// while another window has the focus, and close when they go back by themselves
// (Save, Cancel, a scene picked).
const pad = (n) => String(n).padStart(2, '0')
const on = (value) => value === true || value === 'true'
const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']

// The frame's own scenes (the contract's `scenes.settings`, `scenes.switcher` and
// `scenes.terminal`), and the command that opens each, which also sends it back.
const SETTINGS = 'system/sceneSettings'
// On a desktop every scene's settings are a scene of their own, this and the
// scene's id (the contract's `scenes.settingsWindow`); the plain id is the frame's
// page, System Settings.
const SETTINGS_OF = 'system/sceneSettings#'
const settingsOf = (id) => SETTINGS_OF + id
const settingsFor = (id) => (typeof id === 'string' && id.startsWith(SETTINGS_OF) ? id.slice(SETTINGS_OF.length) : null)
const SWITCHER = 'system/sceneSwitcher'
const TERMINAL = 'system/terminal'
const commandOf = (id) => (id === SWITCHER ? 'sceneSwitcher' : id === TERMINAL ? 'terminal' : 'sceneSettings')
const isSystem = (id) => typeof id === 'string' && id.startsWith('system/')
// The frame's own apps that are scenes like any other, which the frame may have
// (docs/scene-store.md): the scene store and the asset browser, by their sample's
// id, or by their name where a control plane gave them another id. A desktop has
// entries of its own for them, and leaves them out of its scene lists.
const appIs = (id, name) => (scene) =>
  !!scene && (scene.id === id || String(scene.name || '').trim().toLowerCase() === name)
const isStore = appIs('scene-store', 'scene store')
const isAssets = appIs('asset-browser', 'asset browser')
const isFrameApp = (scene) => isStore(scene) || isAssets(scene)
const findScene = (app, test) => (Array.isArray(app.frame.scenes) ? app.frame.scenes.find(test) : undefined)
const storeOf = (app) => findScene(app, isStore)
const assetsOf = (app) => findScene(app, isAssets)
const BAG = 'M6 7V6a6 6 0 0 1 12 0v1h2.5l-1 15h-15l-1-15ZM8 7h8V6a4 4 0 0 0-8 0Z'

// ------------------------------------------------------------ the frame's pages
//
// The frame's own pages (a scene's settings, the frame's, the scene list, the
// terminal, the keyboard on the screen) in this layout's look: a theme is each
// kind of element's classes (docs/jsx-ui.md "Themes"), a string for one box or a
// list for boxes inside each other (a bevel is two or three, as a box has one
// border color). The layout keeps it in its state as `theme`, where the frame
// reads it; not on an ESP32, where the pages keep their own look, nor on e-paper
// but for high contrast.
const CONTRAST = {
  page: 'bg-black text-white',
  bar: 'border-b-2 border-white',
  button: 'font-bold bg-black text-white border-2 border-white active:bg-white active:text-black',
  primary: 'font-bold bg-white text-black border-2 border-white active:bg-black active:text-white',
  selected: 'bg-white text-black border-2 border-white',
  field: 'bg-black text-white border-2 border-white placeholder:text-white focus:border-[#ffff00]',
  option: 'active:bg-white active:text-black',
  picked: 'bg-white text-black',
  switch: 'rounded-full border-2 border-white',
  switchOn: 'rounded-full bg-white border-2 border-white',
  knob: 'rounded-full bg-white',
  knobOn: 'rounded-full bg-black',
  muted: 'text-white',
  card: 'border-2 border-white',
  tile: 'bg-black text-white border-2 border-white active:bg-white active:text-black',
  tileLit: 'bg-black text-white border-4 border-[#ffff00]',
  accent: 'bg-[#ffff00]',
  keyboard: 'bg-black text-white border-t-2 border-white',
  key: 'bg-black text-white border-2 border-white active:bg-white active:text-black',
  keyMod: 'bg-black text-[#ffff00] border-2 border-white active:bg-white active:text-black',
  keyLit: 'bg-white text-black border-2 border-white',
  terminal: 'bg-black text-white',
  prompt: 'font-bold text-[#ffff00]',
}

function dress(app, themes, fallback) {
  if (app.frame.embedded) return
  const name = String(app.state.look || fallback)
  const theme = name === 'contrast' ? CONTRAST : app.frame.paper ? null : themes[name] || null
  const key = theme ? name : ''
  if ((app.state.themeOf || '') === key) return
  frameos.setState('theme', theme)
  frameos.setState('themeOf', key)
}

const THEMES = {
  light: {
    page: 'bg-[#ececec] text-[#1d1d1f]',
    bar: 'bg-[#e3e3e3] border-b-1 border-[#c8c8c8]',
    button: 'rounded-[6px] bg-white border-1 border-[#c4c4c4] active:bg-[#e2e2e2]',
    primary: 'rounded-[6px] bg-[#0a64d8] text-white border-1 border-[#0858c0] active:bg-[#0858c0]',
    selected: 'rounded-[6px] bg-[#d0d0d5] border-1 border-[#b8b8be]',
    field: 'rounded-[6px] bg-white text-[#1d1d1f] border-1 border-[#c4c4c4] focus:border-[#0a64d8] placeholder:text-[#a0a0a5]',
    option: 'rounded-[5px] active:bg-[#0a64d8] active:text-white',
    picked: 'rounded-[5px] bg-[#0a64d8] text-white',
    switch: 'rounded-full bg-[#d9d9de]',
    switchOn: 'rounded-full bg-[#34c759]',
    knob: 'rounded-full bg-white border-1 border-[#c4c4c4]',
    knobOn: 'rounded-full bg-white',
    muted: 'text-[#6e6e73]',
    card: 'rounded-[10px] bg-white border-1 border-[#dcdcdc]',
    tile: 'rounded-[12px] bg-white border-1 border-[#d0d0d0] active:bg-[#f0f0f0]',
    tileLit: 'rounded-[12px] bg-white border-2 border-[#0a64d8]',
    accent: 'bg-[#0a64d8]',
    keyboard: 'bg-[#d1d3d9] text-black',
    key: 'rounded-[6px] bg-white text-black active:bg-[#bfc3cb]',
    keyMod: 'rounded-[6px] bg-[#adb2bb] text-black active:bg-white',
    keyLit: 'rounded-[6px] bg-white text-black border-2 border-[#0a64d8]',
    terminal: 'bg-white text-black',
    prompt: 'font-bold text-[#1d1d1f]',
  },
  dark: {
    page: 'bg-[#1e1e1e] text-[#f5f5f7]',
    bar: 'bg-[#2a2a2a] border-b-1 border-black',
    button: 'rounded-[6px] bg-[#5a5a5e] active:bg-[#6e6e73]',
    primary: 'rounded-[6px] bg-[#0a84ff] text-white active:bg-[#0a64d8]',
    selected: 'rounded-[6px] bg-[#0a84ff] text-white',
    field: 'rounded-[6px] bg-[#2b2b2d] text-white border-1 border-[#3d3d40] focus:border-[#0a84ff] placeholder:text-[#8e8e93]',
    option: 'rounded-[5px] active:bg-[#0a84ff]',
    picked: 'rounded-[5px] bg-[#0a84ff] text-white',
    switch: 'rounded-full bg-[#3a3a3c]',
    switchOn: 'rounded-full bg-[#30d158]',
    knob: 'rounded-full bg-white',
    knobOn: 'rounded-full bg-white',
    muted: 'text-[#98989d]',
    card: 'rounded-[10px] bg-[#2b2b2d]',
    tile: 'rounded-[12px] bg-[#2b2b2d] border-1 border-[#3d3d40] active:bg-[#3a3a3c]',
    tileLit: 'rounded-[12px] bg-[#2b2b2d] border-2 border-[#0a84ff]',
    accent: 'bg-[#0a84ff]',
    keyboard: 'bg-[#2b2b2d] text-white',
    key: 'rounded-[6px] bg-[#6b6b6f] text-white active:bg-[#8e8e93]',
    keyMod: 'rounded-[6px] bg-[#48484a] text-white active:bg-[#6b6b6f]',
    keyLit: 'rounded-[6px] bg-white text-black',
    terminal: 'bg-[#1e1e1e] text-[#f5f5f7]',
    prompt: 'font-bold text-[#30d158]',
  },
}

// Sizes are pixels of the desktop's own: twice that from a short side of 2160 (a 4K
// screen), or of 1000 on e-paper, whose pixels are small, and in proportion under
// 480, which has no room for them. The frame's render scale multiplies on top.
let zoom = 1
let edge = 1 // a hairline's width
let tile = 46 // the Dock's icons, smaller when many scenes share it
const px = (n) => `${Math.round(n * zoom * 10) / 10}px`

function clock(now, twentyFour) {
  const minutes = pad(now.getMinutes())
  if (twentyFour) return `${pad(now.getHours())}:${minutes}`
  return `${now.getHours() % 12 || 12}:${minutes} ${now.getHours() < 12 ? 'AM' : 'PM'}`
}

// Three looks: glass over the wallpaper on a screen; solid on color e-paper, where
// a see-through bar dithers into noise under its words; black on white on a grey
// panel, where the colors would all be one grey.
const GLASS = {
  menu: 'bg-white/65 text-[#1d1d1f]',
  press: 'active:bg-black/10',
  window: 'bg-[#ececec] border-black/30',
  title: 'text-[#4a4a4a]',
  faint: 'text-[#a8a8a8]',
  rule: 'bg-[#d0d0d0]',
  dock: 'bg-white/30 border-white/55',
  divider: 'bg-black/20',
  dot: 'bg-[#1d1d1f]',
  drop: 'bg-[#f2f2f4] border-[#bdbdc2] text-[#1d1d1f]',
  pick: 'hover:bg-[#0a64d8] hover:text-white',
  outline: 'bg-white/25 border-white/70',
  lights: ['#ff5f57', '#febc2e', '#28c840'],
  rims: ['#e0443e', '#d9a024', '#1fa834'],
  marks: ['#7a1712', '#8a5300', '#0b6414'],
  idle: ['#d6d6d6', '#bdbdbd'],
  glyphs: 'opacity-0 group-hover:opacity-100',
  tile: '',
  lift: true,
  ruled: false,
}
const PAPER = {
  ...GLASS,
  menu: 'bg-white text-black',
  window: 'bg-white border-black',
  title: 'text-black',
  faint: 'text-[#808080]',
  rule: 'bg-black',
  dock: 'bg-white border-black',
  divider: 'bg-black',
  dot: 'bg-black',
  drop: 'bg-white border-black text-black',
  outline: 'border-black',
  lift: false,
}
const MONO = {
  ...PAPER,
  ruled: true,
  pick: 'hover:bg-black hover:text-white',
  lights: ['#ffffff', '#ffffff', '#ffffff'],
  rims: ['#000000', '#000000', '#000000'],
  marks: ['#000000', '#000000', '#000000'],
  idle: ['#ffffff', '#808080'],
  glyphs: '',
  tile: 'bg-white border-black',
}
let t = GLASS

// The wallpaper: waves of color under a deep sky, drawn on a 100 x 100 grid and
// stretched to the panel's size. It is the same element from one render to the next
// (memo), so it is laid out and drawn once.
const Wallpaper = memo(({ mono, w, h }) =>
  <svg viewBox={`0 0 ${w} ${h}`} preserveAspectRatio="none" className="w-full h-full">
    <g transform={`scale(${w / 100} ${h / 100})`}>{mono ? <MonoWaves /> : <Waves />}</g>
  </svg>
)

const MonoWaves = () => (
    <g>
      <rect x="0" y="0" width="100" height="100" fill="#dcdcdc" />
      <path fill="#c8c8c8" d="M0 44C18 34 34 50 52 44C70 38 84 30 100 36V100H0Z" />
      <path fill="#b4b4b4" d="M0 62C16 54 32 68 50 63C68 58 82 50 100 56V100H0Z" />
      <path fill="#a0a0a0" d="M0 80C20 72 40 84 60 78C78 73 90 70 100 73V100H0Z" />
    </g>
)

const Waves = () => (
    <g>
      <linearGradient id="macSky" gradientUnits="userSpaceOnUse" x1="0" y1="0" x2="0" y2="100">
        <stop offset="0" stopColor="#1a2f7a" />
        <stop offset="0.45" stopColor="#3a5bd0" />
        <stop offset="1" stopColor="#6d4bd0" />
      </linearGradient>
      <linearGradient id="macWaveA" gradientUnits="userSpaceOnUse" x1="0" y1="30" x2="100" y2="60">
        <stop offset="0" stopColor="#3657e0" />
        <stop offset="1" stopColor="#7b4fe0" />
      </linearGradient>
      <linearGradient id="macWaveB" gradientUnits="userSpaceOnUse" x1="0" y1="50" x2="100" y2="70">
        <stop offset="0" stopColor="#8a3fd8" />
        <stop offset="1" stopColor="#d2459f" />
      </linearGradient>
      <linearGradient id="macWaveC" gradientUnits="userSpaceOnUse" x1="0" y1="66" x2="100" y2="86">
        <stop offset="0" stopColor="#e2508c" />
        <stop offset="1" stopColor="#f6835a" />
      </linearGradient>
      <linearGradient id="macWaveD" gradientUnits="userSpaceOnUse" x1="0" y1="80" x2="100" y2="100">
        <stop offset="0" stopColor="#f79a48" />
        <stop offset="1" stopColor="#fbcf5e" />
      </linearGradient>
      <rect x="0" y="0" width="100" height="100" fill="url(#macSky)" />
      <path fill="url(#macWaveA)" d="M0 40C18 30 34 48 52 41C70 34 84 26 100 33V100H0Z" />
      <path fill="url(#macWaveB)" d="M0 57C16 48 31 63 49 58C67 53 81 44 100 51V100H0Z" />
      <path fill="url(#macWaveC)" d="M0 73C20 65 38 79 58 73C76 67 88 63 100 67V100H0Z" />
      <path fill="url(#macWaveD)" d="M0 88C22 82 44 93 66 87C82 83 92 80 100 82V100H0Z" />
    </g>
)

// The menu bar's icons, in its text color.
const Mark = () => (
  <svg viewBox="0 0 46 54" className={`w-[${px(14)}] h-[${px(16)}]`}>
    <path fill="currentColor" d="M0 0H46V5H5V30H0ZM26 49H41V32H46V54H26Z" />
    <rect x="7" y="36" width="12" height="11" rx="1.4" fill="currentColor" />
    <rect x="20" y="24" width="12" height="11" rx="1.4" fill="currentColor" />
    <rect x="33" y="12" width="12.5" height="11.5" rx="1.4" fill="currentColor" />
  </svg>
)

const Toggles = () => (
  <svg viewBox="0 0 18 15" className={`w-[${px(17)}] h-[${px(14)}]`}>
    <rect x="0.6" y="0.6" width="16.8" height="5.8" rx="2.9" fill="none" stroke="currentColor" strokeWidth="1.1" />
    <circle cx="13.9" cy="3.5" r="1.9" fill="currentColor" />
    <rect x="0.6" y="8.6" width="16.8" height="5.8" rx="2.9" fill="none" stroke="currentColor" strokeWidth="1.1" />
    <circle cx="4.1" cy="11.5" r="1.9" fill="currentColor" />
  </svg>
)

// The Wi-Fi fan, its arcs lit by the signal; nothing on a frame that cannot tell.
function Wifi({ rssi }) {
  if (typeof rssi !== 'number') return null
  const level = rssi >= -60 ? 3 : rssi >= -72 ? 2 : 1
  const arc = (lit) => (lit ? 1 : 0.3)
  return (
    <svg viewBox="0 0 20 15" className={`w-[${px(18)}] h-[${px(14)}]`}>
      <circle cx="10" cy="12.6" r="1.7" fill="currentColor" />
      <path d="M6.8 9.5A4.5 4.5 0 0 1 13.2 9.5" fill="none" stroke="currentColor" strokeOpacity={arc(level >= 1)} strokeWidth="1.8" strokeLinecap="round" />
      <path d="M4 6.6A8.5 8.5 0 0 1 16 6.6" fill="none" stroke="currentColor" strokeOpacity={arc(level >= 2)} strokeWidth="1.8" strokeLinecap="round" />
      <path d="M1.2 3.8A12.5 12.5 0 0 1 18.8 3.8" fill="none" stroke="currentColor" strokeOpacity={arc(level >= 3)} strokeWidth="1.8" strokeLinecap="round" />
    </svg>
  )
}

function Battery({ percent, mono }) {
  if (typeof percent !== 'number') return null
  const low = percent <= 15 && !mono
  return (
    <svg viewBox="0 0 27 13" className={`w-[${px(26)}] h-[${px(13)}]`}>
      <rect x="0.6" y="0.6" width="23" height="11.8" rx="3.6" fill="none" stroke="currentColor" strokeOpacity="0.5" strokeWidth="1.2" />
      <rect x="2.2" y="2.2" width={Math.max(1.5, (19.8 * Math.min(100, percent)) / 100)} height="8.6" rx="2" fill={low ? '#ff3b30' : 'currentColor'} />
      <path d="M25 4.4C26.2 4.8 26.6 5.6 26.6 6.5C26.6 7.4 26.2 8.2 25 8.6Z" fill="currentColor" fillOpacity="0.5" />
    </svg>
  )
}

// A word or an icon in the menu bar, lit while pressed or while its menu is open.
const Menu = ({ className = '', lit = false, onClick, onPointerMove, children }) => (
  <div
    className={`flex items-center shrink-0 h-[${px(22)}] gap-[${px(9)}] px-[${px(8)}] rounded-[${px(5)}] whitespace-nowrap ${
      lit ? 'bg-black/15' : t.press
    } ${className}`}
    onClick={onClick}
    onPointerMove={onPointerMove}
  >
    {children}
  </div>
)

// A traffic light. Its glyph shows while the pointer is over the three of them,
// and always on a grey panel, where the three are alike. A window behind has them
// grey.
const Light = ({ index, dim = false, onClick, children }) => (
  <div className={`flex p-[${px(4)}]`} onClick={onClick}>
    <svg viewBox="0 0 12 12" className={`w-[${px(12)}] h-[${px(12)}]`}>
      <circle cx="6" cy="6" r="5.6" fill={dim ? t.idle[0] : t.lights[index]} stroke={dim ? t.idle[1] : t.rims[index]} strokeWidth="0.7" />
    </svg>
    <svg viewBox="0 0 12 12" className={`absolute top-[${px(4)}] left-[${px(4)}] w-[${px(12)}] h-[${px(12)}] ${t.glyphs}`}>
      {children}
    </svg>
  </div>
)

const Lights = ({ dim, onClose, onMinimize, onZoom }) => (
  <div className="group flex flex-1 basis-0 min-w-0 items-center">
    <Light index={0} dim={dim} onClick={onClose}>
      <path d="M3.9 3.9L8.1 8.1M8.1 3.9L3.9 8.1" stroke={t.marks[0]} strokeWidth="1.2" strokeLinecap="round" />
    </Light>
    <Light index={1} dim={dim} onClick={onMinimize}>
      <path d="M3.2 6H8.8" stroke={t.marks[1]} strokeWidth="1.3" strokeLinecap="round" />
    </Light>
    <Light index={2} dim={dim} onClick={onZoom}>
      <path d="M3.5 3.5H7.3L3.5 7.3ZM8.5 8.5H4.7L8.5 4.7Z" fill={t.marks[2]} />
    </Light>
  </div>
)

// No shadows to be had: two see-through rings under the window, deeper at the
// bottom, lift it off the wallpaper. On paper and grey panels its line does that.
const Lifted = ({ children }) =>
  t.lift ? (
    <div className={`flex flex-col flex-1 min-h-0 rounded-[${px(13)}] bg-black/10 pt-[${px(1)}] px-[${px(1)}] pb-[${px(3)}]`}>
      <div className={`flex flex-col flex-1 min-h-0 rounded-[${px(12)}] bg-black/10 pb-[${px(1)}]`}>{children}</div>
    </div>
  ) : (
    children
  )

// The window: rounded corners, a title bar with the lights and the name in the
// middle, and a strip at the bottom as deep as the corners are round, which keeps
// the square scene off them.
const Window = ({ title, onClose, onMinimize, onZoom, children }) => (
  <div className={`flex flex-col flex-1 min-h-0 rounded-[${px(11)}] border-[${edge}px] ${t.window}`}>
    <div className={`flex items-center shrink-0 h-[${px(30)}] px-[${px(8)}]`}>
      <Lights onClose={onClose} onMinimize={onMinimize} onZoom={onZoom} />
      <span className={`shrink min-w-0 truncate font-semibold ${t.title}`}>{title}</span>
      <div className="flex-1 basis-0" />
    </div>
    <div className={`shrink-0 h-[${edge}px] ${t.rule}`} />
    <div className="flex flex-col flex-1 min-h-0">{children}</div>
    <div className={`shrink-0 h-[${px(10)}]`} />
  </div>
)

