// ---------------------------------------------------------------- the desktop
//
// What it keeps, in the layout's state (it goes along from scene to scene on a
// Pi, and is gone at a restart): `wins`, the windows open in the order they were
// opened, each {id, x, y, w, h, z, max, min, snap}, in the desktop's pixels (x to
// h is the window's own box, kept while it fills the desktop or is snapped to a
// half of it, `snap` 'l' or 'r'; a built-in scene's also its `title`); `boxes`,
// where each scene's window was when it closed, by scene id; `last`, the
// scene that had the focus at the last render; `asked`, the scene this layout last
// brought forward itself; `gone`, the scene whose window was just closed; `picked`,
// the desktop icon picked; `full`, `menu`, `peek` and `drag`, a move or a size in
// progress.

const winsOf = (app) => (Array.isArray(app.state.wins) ? app.state.wins : [])
const topZ = (wins) => wins.reduce((z, w) => Math.max(z, w.z || 0), 0)

function clamp(win, deskW, deskH) {
  const minW = Math.min(deskW, Math.round(160 * zoom))
  const minH = Math.min(deskH, Math.round(100 * zoom))
  win.w = Math.round(Math.max(minW, Math.min(win.w, deskW)))
  win.h = Math.round(Math.max(minH, Math.min(win.h, deskH)))
  // A title bar stays where the pointer can get at it.
  const grip = Math.round(48 * zoom)
  win.x = Math.round(Math.max(grip - win.w, Math.min(win.x, deskW - grip)))
  win.y = Math.round(Math.max(0, Math.min(win.y, deskH - Math.round(24 * zoom))))
  return win
}

const boxesOf = (app) => (app.state.boxes && typeof app.state.boxes === 'object' ? app.state.boxes : {})

// A closed window's box, for when its scene opens again.
function keep(app, win) {
  const { x, y, w, h, max, snap } = win
  frameos.setState('boxes', { ...boxesOf(app), [win.id]: { x, y, w, h, max, snap } })
}

// The scene's own area in a new window, from the layout's "Window size" (`WxH`, in
// a desktop's pixels like every size here); null for the whole desktop.
function ownSize(app) {
  const m = /^(\d+)x(\d+)$/.exec(String(app.state.windowSize || '800x480'))
  return m ? { w: Math.round(Number(m[1]) * zoom), h: Math.round(Number(m[2]) * zoom) } : null
}

function placed(app, id, wins, deskW, deskH) {
  const win = { id, z: topZ(wins) + 1 }
  // Where it was when it closed, if it was open before.
  const kept = boxesOf(app)[id]
  if (kept) return clamp({ ...kept, ...win }, deskW, deskH)
  // Otherwise the layout's size, its borders and title bar around it, cascading
  // from the corner and all of it on the desktop.
  const step = Math.round(28 * zoom) * (wins.length % 6)
  const size = ownSize(app)
  const w = size ? size.w + 4 * edge + Math.round(4 * zoom) : deskW + 1
  const h = size ? size.h + 4 * edge + Math.round(30 * zoom) : deskH + 1
  if (w <= deskW && h <= deskH) {
    const x = Math.min(Math.round(96 * zoom) + step, deskW - w)
    const y = Math.min(Math.round(16 * zoom) + step, deskH - h)
    return clamp({ ...win, x, y, w, h, max: false }, deskW, deskH)
  }
  // Where it does not fit, the first window fills the desktop, which is what the
  // frame looked like before anything else was opened, and the next ones take
  // most of it; set to the whole desktop, every one fills it.
  const shown = wins.filter((other) => !other.min).length
  const box = { x: Math.round(96 * zoom) + step, y: Math.round(16 * zoom) + step, w: deskW * 0.62, h: deskH * 0.62 }
  return clamp({ ...win, ...box, max: !size || shown === 0 }, deskW, deskH)
}

// What another desktop had open when this layout was chosen in its place (its
// `openScenes`, handed over by the runtime: docs/scene-layouts.md "Windows"): a
// window each, cascading in that order, so the one that had the focus is on top.
function opened(app, names, titleOf, deskW, deskH) {
  const wins = []
  for (const id of Array.isArray(app.state.openScenes) ? app.state.openScenes : []) {
    if (typeof id !== 'string' || wins.some((w) => w.id === id) || !(names[id] || isSystem(id))) continue
    const win = placed(app, id, wins, deskW, deskH)
    if (isSystem(id)) win.title = titleOf(id, names)
    wins.push(win)
  }
  return wins
}

// What is open, the one with the focus last: what a layout chosen in this one's
// place opens (`openScenes`).
function keepOpen(app, wins, current) {
  const order = wins
    .filter((w) => w.id !== current)
    .sort((a, b) => (a.z || 0) - (b.z || 0))
    .map((w) => w.id)
  if (wins.some((w) => w.id === current)) order.push(current)
  if (JSON.stringify(order) !== JSON.stringify(app.state.openScenes || [])) frameos.setState('openScenes', order)
}

// Where a window is drawn: its own box, the whole desktop, or a half of it.
function boxOf(win, deskW, deskH) {
  const half = Math.round(deskW / 2)
  if (win.max) return { x: 0, y: 0, w: deskW, h: deskH }
  if (win.snap === 'l') return { x: 0, y: 0, w: half, h: deskH }
  if (win.snap === 'r') return { x: half, y: 0, w: deskW - half, h: deskH }
  return { x: win.x, y: win.y, w: win.w, h: win.h }
}

// What a press, a key or the Start menu does to the windows. Each one reads the
// state afresh: a drag's moves come faster than renders.
function actions(app) {
  const current = app.frame.sceneId
  const update = (id, change) => {
    const next = winsOf(app).map((w) => (w.id === id ? { ...w, ...change(w) } : w))
    frameos.setState('wins', next)
  }
  // Every window this layout brings forward goes through here, so a built-in
  // scene that loses the focus some other way is known to have gone back.
  const go = (id) => {
    frameos.setState('asked', id)
    frameos.dispatch('setCurrentScene', { sceneId: id })
  }
  const focus = (id) => {
    frameos.setState('menu', false)
    update(id, () => ({ min: false }))
    if (id !== current) go(id)
  }
  const open = (id) => {
    frameos.setState('menu', false)
    if (winsOf(app).some((w) => w.id === id)) return focus(id)
    if (id !== current) go(id)
    else if (app.state.gone === id) frameos.setState('gone', null)
  }
  // Read when a handler runs, not when it was drawn: a press before it may have
  // brought another window forward.
  const showing = () => app.frame.sceneId
  const windowOf = (id) => winsOf(app).find((w) => w.id === id)
  // A built-in scene opens over a scene. Over another built-in one, that one stays
  // open in its window, and the scene window on top comes forward to open it over;
  // with none, the built-in one goes back where it came from. Either way the
  // focus is this layout's doing (`asked`): the one left open keeps its window.
  const overAScene = () => {
    const now = showing()
    if (!isSystem(now)) return
    const top = winsOf(app)
      .filter((w) => !isSystem(w.id) && !w.min)
      .sort((a, b) => (b.z || 0) - (a.z || 0))[0]
    if (top) go(top.id)
    else frameos.dispatch(commandOf(now))
  }
  // A scene's settings, from the gear on its title bar: a window of their own,
  // opened over the scene's window brought forward first; open already, that
  // window comes forward as it was left.
  const sceneSettings = (id) => {
    frameos.setState('menu', false)
    if (windowOf(settingsOf(id))) return focus(settingsOf(id))
    if (id !== showing()) go(id)
    frameos.dispatch('sceneSettings', {})
    frameos.setState('asked', settingsOf(id))
  }
  // The frame's settings, one window: Start's Control Panel, the tray, the gear in
  // a scene's settings.
  const controlPanel = () => {
    frameos.setState('menu', false)
    if (windowOf(SETTINGS)) return focus(SETTINGS)
    overAScene()
    frameos.dispatch('sceneSettings', { page: 'frame' })
    frameos.setState('asked', SETTINGS)
  }
  // Start's Terminal: open already, it comes forward as it was left.
  const terminal = () => {
    frameos.setState('menu', false)
    if (windowOf(TERMINAL)) return focus(TERMINAL)
    overAScene()
    frameos.dispatch('terminal')
    frameos.setState('asked', TERMINAL)
  }
  // The desktop's Programs: the scene list, one window.
  const programs = () => {
    frameos.setState('menu', false)
    if (windowOf(SWITCHER)) return focus(SWITCHER)
    overAScene()
    frameos.dispatch('sceneSwitcher')
    frameos.setState('asked', SWITCHER)
  }
  // The window in front went away: the next one down takes the focus.
  const nextAfter = (id) =>
    winsOf(app)
      .filter((w) => w.id !== id && !w.min)
      .sort((a, b) => (b.z || 0) - (a.z || 0))[0]
  const minimize = (id) => {
    update(id, () => ({ min: true }))
    const next = id === current ? nextAfter(id) : null
    if (next) go(next.id)
  }
  // A built-in scene with the focus closes as its own Cancel does, back to the
  // scene it was opened over.
  const close = (id) => {
    const next = id === current ? nextAfter(id) : null
    const win = winsOf(app).find((w) => w.id === id)
    if (win) keep(app, win)
    frameos.setState('wins', winsOf(app).filter((w) => w.id !== id))
    if (id !== current) return
    frameos.setState('gone', id)
    frameos.setState('full', false)
    if (isSystem(id)) frameos.dispatch(commandOf(id))
    else if (next) go(next.id)
  }
  const toggleMax = (id) => update(id, (w) => ({ max: !w.max, snap: null }))
  const toggleFull = () => {
    frameos.setState('menu', false)
    frameos.setState('peek', false)
    frameos.setState('full', !on(app.state.full))
  }
  // Alt+Tab: the window that had the focus before this one, so twice comes back;
  // with Shift, the one at the bottom, so every window comes round in turn.
  const cycle = (back) => {
    const others = winsOf(app)
      .filter((w) => w.id !== current)
      .sort((a, b) => (b.z || 0) - (a.z || 0))
    const next = back ? others[others.length - 1] : others[0]
    if (next) focus(next.id)
    return !!next
  }
  return { update, focus, open, sceneSettings, controlPanel, terminal, programs, minimize, close, toggleMax, toggleFull, cycle }
}

// A scene on the desktop: a picture in a frame.
const SceneIcon = ({ size = 32 }) => (
  <svg viewBox="0 0 32 32" className={`w-[${px(size)}] h-[${px(size)}]`}>
    <rect x="1" y="3" width="30" height="26" fill="#8b5a2b" stroke="#000000" />
    <rect x="5" y="7" width="22" height="18" fill="#87ceeb" stroke="#3b2410" />
    <path fill="#2e8b57" d="M5 25L12 15L17 21L21 17L27 25Z" />
    <circle cx="22" cy="11" r="2.5" fill="#ffd700" />
  </svg>
)

// The scene list on the desktop: a folder.
const FolderIcon = ({ size = 32 }) => (
  <svg viewBox="0 0 32 32" className={`w-[${px(size)}] h-[${px(size)}]`}>
    <path fill="#c8a000" stroke="#000000" d="M2.5 7.5H12.5L15 10H29.5V27.5H2.5Z" />
    <path fill="#ffe680" stroke="#000000" d="M2.5 12.5H29.5V27.5H2.5Z" />
  </svg>
)

// A built-in scene's window has the gear (the terminal its prompt), the store's its
// bag, the asset browser's a picture, a scene's the window.
let storeId = null
let assetsId = null
const iconOf = (id) =>
  id === TERMINAL ? (
    <TerminalIcon />
  ) : isSystem(id) ? (
    <Gear />
  ) : id === storeId ? (
    <StoreIcon />
  ) : id === assetsId ? (
    <SceneIcon size={16} />
  ) : (
    <WindowIcon />
  )

// What a built-in scene's window is called before it has shown its page here.
const titleOf = (id, names) => {
  const scene = settingsFor(id)
  if (scene) return `${names[scene] || scene} Properties`
  return id === SWITCHER ? 'Programs' : id === TERMINAL ? 'Terminal' : 'Control Panel'
}

// What a built-in scene's window is called, by the page it shows.
function systemTitle(app, names) {
  const scene = settingsFor(app.frame.sceneId)
  if (scene) return `${names[scene] || app.state.openedOver || scene} Properties`
  if (app.frame.sceneId === SWITCHER) return 'Programs'
  if (app.frame.sceneId === TERMINAL) return 'Terminal'
  const page = app.frame.sceneName
  if (page === 'Frame settings') return 'Control Panel'
  if (page === 'Layout settings') return 'Display Properties'
  return app.state.openedOver ? `${app.state.openedOver} Properties` : 'Properties'
}

function desktop(app, now, width, height) {
  const scale = app.frame.scale || 1
  const builtIn = app.frame.systemScene === true
  const current = app.frame.sceneId
  const names = {}
  for (const scene of app.frame.scenes) names[scene.id] = scene.name || scene.id
  if (!builtIn && current && !names[current]) names[current] = app.frame.sceneName || current
  const store = storeOf(app)
  const assets = assetsOf(app)
  storeId = store ? store.id : null
  assetsId = assets ? assets.id : null
  const frameApps = [store, assets].filter(Boolean)
  const programs = app.frame.scenes.filter((scene) => !isFrameApp(scene))
  const taskH = Math.round(40 * zoom) + 2 * edge
  const deskW = width
  const deskH = Math.max(1, height - taskH)

  // Whatever brought a scene forward (a window, Start, an icon, the scene list, a
  // button, the API), its window is open and on top, and the one it took the
  // focus from is next below it. A built-in scene's window is named by what it
  // shows while it has the focus, and closes once it has gone back by itself: the
  // focus left it for a scene, and not because this layout moved it. One that
  // opened another (the gear in a scene's settings opening Control Panel) did not
  // go back, and stays open.
  // A layout just chosen in another desktop's place has no windows of its own yet:
  // it opens what that one had open.
  const fresh = !Array.isArray(app.state.wins)
  const saved = fresh ? opened(app, names, titleOf, deskW, deskH) : winsOf(app)
  const wins = saved.filter((w) => w && (names[w.id] || isSystem(w.id)))
  let changed = fresh ? wins.length > 0 : wins.length !== saved.length
  if (current) {
    let win = wins.find((w) => w.id === current)
    if (!win && app.state.gone !== current) {
      win = placed(app, current, wins, deskW, deskH)
      wins.push(win)
      changed = true
    }
    if (win && builtIn && win.title !== systemTitle(app, names)) {
      win.title = systemTitle(app, names)
      changed = true
    }
    if (app.state.last !== current) {
      if (win && win.min) win.min = false
      const before = wins.find((w) => w.id === app.state.last)
      if (before && isSystem(before.id) && !isSystem(current) && app.state.asked !== current) {
        keep(app, before)
        wins.splice(wins.indexOf(before), 1)
      } else if (before) before.z = topZ(wins) + 1
      if (app.state.gone && app.state.gone !== current) frameos.setState('gone', null)
      if (app.state.asked) frameos.setState('asked', null)
      frameos.setState('last', current)
      changed = true
    }
  }
  if (changed) frameos.setState('wins', wins)
  keepOpen(app, wins, current)
  for (const win of wins) if (isSystem(win.id)) names[win.id] = win.title || titleOf(win.id, names)

  const focused = wins.find((w) => w.id === current && !w.min)
  const full = !!focused && on(app.state.full)
  const startMenu = on(app.state.menu)
  const { update, focus, open, sceneSettings, controlPanel, terminal, programs: sceneList, minimize, close, toggleMax, toggleFull } =
    actions(app)

  // A press on a title bar moves the window, one on its border sizes it from
  // that edge; the moves that follow are captured by what was pressed. Let go
  // at the top of the desktop, a moved window fills it, at the left or right
  // edge it takes that half; dragged away again, it has its own size back.
  const startDrag = (drawn, mode) => (e) => {
    frameos.setState('picked', null)
    // As it is now, not as it was drawn: a size may have come since.
    const win = winsOf(app).find((w) => w.id === drawn.id) || drawn
    const box = boxOf(win, deskW, deskH)
    const docked = !!(win.max || win.snap)
    // A half sized from its edge is a window of that size from then on.
    if (docked && mode !== 'move') update(win.id, () => ({ ...box, snap: null }))
    frameos.setState('drag', {
      id: win.id,
      mode,
      x: e.x,
      y: e.y,
      from: box,
      own: { w: win.w, h: win.h },
      docked: docked && mode === 'move',
      at: null,
    })
    if (win.id !== current) focus(win.id)
  }
  const dragTo = (e) => {
    const drag = app.state.drag
    if (!drag || !e.buttons) return
    const dx = (e.x - drag.x) / scale
    const dy = (e.y - drag.y) / scale
    if (drag.mode === 'move') {
      const x = e.x / scale
      const y = e.y / scale
      const at = y <= 2 ? 'max' : x <= 2 ? 'l' : x >= deskW - 3 ? 'r' : null
      if (drag.docked) {
        // A press that does not move leaves it be (a double click sizes it back).
        if (Math.abs(dx) + Math.abs(dy) < 8 * zoom) return
        // Its own size, with the pointer as far across the title bar as it was.
        const across = (drag.x / scale - drag.from.x) / drag.from.w
        const from = { x: drag.x / scale - across * drag.own.w, y: drag.from.y, w: drag.own.w, h: drag.own.h }
        frameos.setState('drag', { ...drag, at, docked: false, from })
        update(drag.id, () => ({ ...clamp({ ...from, x: from.x + dx, y: from.y + dy }, deskW, deskH), max: false, snap: null }))
        return
      }
      if (at !== drag.at) frameos.setState('drag', { ...drag, at })
    }
    const f = drag.from
    update(drag.id, () => {
      const box = { ...f }
      if (drag.mode === 'move') {
        box.x = f.x + dx
        box.y = f.y + dy
      } else {
        if (drag.mode.includes('l')) {
          box.x = Math.min(f.x + dx, f.x + f.w - 80 * zoom)
          box.w = f.w - (box.x - f.x)
        }
        if (drag.mode.includes('r')) box.w = f.w + dx
        if (drag.mode.includes('t')) {
          box.y = Math.max(0, Math.min(f.y + dy, f.y + f.h - 60 * zoom))
          box.h = f.h - (box.y - f.y)
        }
        if (drag.mode.includes('b')) box.h = f.h + dy
      }
      return clamp(box, deskW, deskH)
    })
  }
  const endDrag = () => {
    const drag = app.state.drag
    frameos.setState('drag', null)
    if (drag && drag.mode === 'move' && drag.at && !drag.docked) {
      update(drag.id, () => (drag.at === 'max' ? { max: true, snap: null } : { max: false, snap: drag.at }))
    }
  }
  const corner = 14 * zoom
  const edgeOf = (e) => {
    const x = e.localX < corner ? 'l' : e.localX > e.width - corner ? 'r' : ''
    const y = e.localY < corner ? 't' : e.localY > e.height - corner ? 'b' : ''
    return y + x || 'b'
  }
  const sizing = (win) => ({
    onPointerDown: (e) => startDrag(win, edgeOf(e))(e),
    onPointerMove: dragTo,
    onPointerUp: endDrag,
  })
  const moving = (win) => ({
    onPointerDown: startDrag(win, 'move'),
    onPointerMove: dragTo,
    onPointerUp: endDrag,
    onDoubleClick: () => toggleMax(win.id),
  })

  const windowOf = (win) => {
    const active = win.id === current
    const box = boxOf(win, deskW, deskH)
    return (
      <Frame
        className={`absolute left-[${box.x}px] top-[${box.y}px] w-[${box.w}px] h-[${box.h}px]`}
        frame={win.max ? {} : sizing(win)}
      >
        <TitleBar
          title={names[win.id]}
          icon={iconOf(win.id)}
          active={active}
          maximized={win.max}
          onSettings={isSystem(win.id) ? undefined : () => sceneSettings(win.id)}
          onMinimize={() => minimize(win.id)}
          onMaximize={() => toggleMax(win.id)}
          onClose={() => close(win.id)}
          {...moving(win)}
        />
        <div className="relative flex flex-col flex-1 min-h-0">
          {active ? <yield /> : <Scene id={win.id} />}
          {/* A press on a window behind brings it forward, and is only that. */}
          {active ? null : <div className="absolute inset-0" onPointerDown={() => focus(win.id)} />}
        </div>
      </Frame>
    )
  }

  // Where a window let go now would go: its outline, four bars, over the windows.
  const outline = () => {
    const drag = app.state.drag
    if (!drag || drag.mode !== 'move' || !drag.at || drag.docked) return null
    const b = boxOf({ max: drag.at === 'max', snap: drag.at }, deskW, deskH)
    const t = Math.max(2, Math.round(3 * zoom))
    const bar = (x, y, w, h) => <div className={`absolute left-[${x}px] top-[${y}px] w-[${w}px] h-[${h}px] bg-[#404040]`} />
    return [bar(b.x, b.y, b.w, t), bar(b.x, b.y + b.h - t, b.w, t), bar(b.x, b.y, t, b.h), bar(b.x + b.w - t, b.y, t, b.h)]
  }

  // The scenes as icons, in columns from the top left: a click picks one, a
  // double click opens it.
  const icons = () => {
    const iconW = Math.round(80 * zoom)
    const iconH = Math.round(72 * zoom)
    const perColumn = Math.max(1, Math.floor((deskH - 8 * zoom) / iconH))
    // The frame's own apps, not its scenes (Start has those): the scene list, the
    // store and the asset browser where the frame has them, the terminal and the
    // frame's settings.
    const items = [
      { id: SWITCHER, label: 'Programs', icon: <FolderIcon />, go: sceneList },
      ...(store ? [{ id: store.id, label: names[store.id], icon: <StoreIcon size={32} />, go: () => open(store.id) }] : []),
      ...(assets ? [{ id: assets.id, label: names[assets.id], icon: <SceneIcon />, go: () => open(assets.id) }] : []),
      { id: TERMINAL, label: 'Terminal', icon: <TerminalIcon size={32} />, go: terminal },
      { id: SETTINGS, label: 'Control Panel', icon: <Gear size={32} />, go: controlPanel },
    ]
    return items.map((item, i) => {
      const x = Math.round(8 * zoom + Math.floor(i / perColumn) * iconW)
      const y = Math.round(8 * zoom + (i % perColumn) * iconH)
      const picked = app.state.picked === item.id
      return (
        <div
          className={`absolute left-[${x}px] top-[${y}px] w-[${iconW}px] h-[${iconH}px] flex flex-col items-center gap-[${px(4)}]`}
          onClick={() => frameos.setState('picked', item.id)}
          onDoubleClick={() => (frameos.setState('picked', null), item.go())}
        >
          {item.icon}
          <span
            className={`max-w-[${iconW}px] px-[${px(2)}] truncate text-white text-[${px(13)}] ${picked ? 'bg-[#000080]' : ''}`}
          >
            {item.label}
          </span>
        </div>
      )
    })
  }

  if (full) {
    // The panel is the window's. The pointer at the bottom edge peeks at the
    // taskbar; moved back over the window, the taskbar goes again, unless Start
    // is open over it.
    const peek = on(app.state.peek) || startMenu
    return (
      <div className="relative w-full h-full bg-[#008080] text-black">
        <div className="absolute inset-0 flex flex-col">
          <yield />
        </div>
        {!peek ? (
          <div className="absolute left-0 bottom-0 w-full h-[2px]" onPointerMove={() => frameos.setState('peek', true)} />
        ) : startMenu ? null : (
          <div className={`absolute left-0 top-0 w-full h-[${deskH}px]`} onPointerMove={() => frameos.setState('peek', false)} />
        )}
        {startMenu ? <div className="absolute inset-0" onPointerDown={() => frameos.setState('menu', false)} onClick={() => {}} /> : null}
        {startMenu ? menu() : null}
        {peek ? bar() : null}
      </div>
    )
  }

  const shown = wins.filter((w) => !w.min && !(focused && w.id === focused.id)).sort((a, b) => (a.z || 0) - (b.z || 0))
  if (focused) shown.push(focused)
  return (
    <div className={`relative flex flex-col w-full h-full bg-[#008080] text-black text-[${px(16)}]`}>
      <div className="relative flex-1 min-h-0" onClick={() => frameos.setState('picked', null)}>
        {icons()}
        {shown.map(windowOf)}
        {outline()}
      </div>
      {startMenu ? <div className="absolute inset-0" onPointerDown={() => frameos.setState('menu', false)} onClick={() => {}} /> : null}
      {startMenu ? menu() : null}
      {bar()}
    </div>
  )

  function bar() {
    const taskW = Math.round(Math.min(160 * zoom, Math.max(48 * zoom, (width - 220 * zoom) / Math.max(1, wins.length))))
    return (
      <Taskbar className={full ? 'absolute left-0 bottom-0 w-full' : ''}>
        <Toggle pressed={startMenu} className="shrink-0" onClick={() => frameos.setState('menu', !startMenu)}>
          <Logo />
          <span className="font-bold whitespace-nowrap">Start</span>
        </Toggle>
        <div className={`flex flex-1 min-w-0 gap-[${px(4)}]`}>
          {wins.map((win) => {
            const front = win.id === current && !win.min
            return (
              <Toggle
                pressed={front}
                className={`w-[${taskW}px] min-w-0`}
                onClick={() => (front ? minimize(win.id) : focus(win.id))}
              >
                {iconOf(win.id)}
                <span className="flex-1 font-bold truncate">{names[win.id]}</span>
              </Toggle>
            )
          })}
        </div>
        <Tray app={app} now={now} onClick={controlPanel} />
      </Taskbar>
    )
  }

  function menu() {
    const Item = ({ onClick, children }) => (
      <div className={`flex items-center gap-[${px(8)}] h-[${px(30)}] px-[${px(8)}] hover:bg-[#000080] hover:text-white`} onClick={onClick}>
        {children}
      </div>
    )
    const Rule = () => (
      <div className={`flex flex-col py-[${px(3)}]`}>
        <div className={`h-[${edge}px] bg-[#808080]`} />
        <div className={`h-[${edge}px] bg-white`} />
      </div>
    )
    const menuW = Math.round(Math.min(width - 8 * zoom, 240 * zoom))
    // The frame's own apps on top, as an update service was, over a rule.
    const menuH = Math.round(
      Math.min(deskH - 8 * zoom, (30 * (programs.length + 3 + frameApps.length) + 22 + (frameApps.length ? 8 : 0)) * zoom)
    )
    // The menu takes a press itself: the cover under it closes the menu on a press,
    // and a render before the release would take the item away from the click.
    return (
      <Frame className={`absolute left-[${px(2)}] bottom-[${taskH - edge}px] w-[${menuW}px] h-[${menuH}px]`} frame={{ onPointerDown: () => {} }}>
        <div className="flex flex-1 min-h-0">
          <div className={`flex flex-col justify-end w-[${px(24)}] bg-gradient-to-b from-[#000080] to-[#1084d0] text-white font-bold text-[${px(13)}]`}>
            <span className={`px-[${px(4)}] pb-[${px(6)}]`}>98</span>
          </div>
          <div className="flex flex-col flex-1 min-w-0">
            {frameApps.map((scene) => (
              <Item onClick={() => open(scene.id)}>
                {iconOf(scene.id)}
                <span className="flex-1 truncate">{names[scene.id]}</span>
              </Item>
            ))}
            {frameApps.length ? <Rule /> : null}
            <div className="flex flex-col flex-1 min-h-0 overflow-y-auto">
              {programs.map((scene) => (
                <Item onClick={() => open(scene.id)}>
                  <WindowIcon />
                  <span className="flex-1 truncate">{scene.name || scene.id}</span>
                </Item>
              ))}
            </div>
            <Rule />
            <Item onClick={toggleFull}>
              <MaximizeGlyph />
              <span className="flex-1 truncate">Full screen</span>
            </Item>
            <Item onClick={controlPanel}>
              <Gear />
              <span className="flex-1 truncate">Control Panel</span>
            </Item>
            <Item onClick={terminal}>
              <TerminalIcon />
              <span className="flex-1 truncate">Terminal</span>
            </Item>
          </div>
        </div>
      </Frame>
    )
  }
}

// F11 gives the panel to the window in front and takes it back; Escape closes
// Start and leaves the full screen; Alt+Tab brings the window before forward
// (Shift: the one at the bottom), Alt+F4 closes the one in front. The scene
// heard the key first.
export function onEvent(app, context) {
  if (context.event !== 'keyDown' || !Array.isArray(app.frame.scenes) || !windowsOn(app)) return false
  const key = context.payload && context.payload.key
  if (key === 'F11') {
    frameos.setState('peek', false)
    frameos.setState('full', !on(app.state.full))
    return true
  }
  if (key === 'Escape' && (on(app.state.menu) || on(app.state.full))) {
    frameos.setState('menu', false)
    frameos.setState('full', false)
    return true
  }
  const alt = context.payload.alt === true
  if (key === 'Tab' && alt) return actions(app).cycle(context.payload.shift === true)
  if (key === 'F4' && alt && app.frame.sceneId) {
    actions(app).close(app.frame.sceneId)
    return true
  }
  return false
}

const windowsOn = (app) => app.state.windows !== false && app.state.windows !== 'false'

export function get(app) {
  // app.frame's size is the panel's over the render scale, before the frame's rotation.
  const turned = (app.frame.rotate || 0) % 180 !== 0
  const width = turned ? app.frame.height : app.frame.width
  const height = turned ? app.frame.width : app.frame.height
  const shortSide = Math.min(app.frame.width, app.frame.height)
  zoom = shortSide >= (app.frame.paper ? 1000 : 2160) ? 2 : shortSide >= 480 ? 1 : shortSide / 480
  edge = Math.max(1, Math.round(zoom))
  const now = new Date()
  dress(app, THEMES, 'standard')
  // The clock changes on the minute: nothing to draw until then.
  frameos.setNextSleep(60 - now.getSeconds())
  if (Array.isArray(app.frame.scenes) && windowsOn(app)) return desktop(app, now, width, height)
  // One scene at a time: nothing else is open, nothing for another layout to open.
  if (Array.isArray(app.state.openScenes) && app.state.openScenes.length) frameos.setState('openScenes', [])
  // The words beside the gear need room: nothing else gives way for them.
  const roomy = width >= 640 * Math.max(zoom, 1)
  const name = app.frame.sceneName || 'FrameOS'
  const builtIn = app.frame.systemScene === true
  const controlPanel = builtIn && name.includes('settings')
  // The terminal (not on an ESP32, where app.frame.sceneId is not there either).
  const terminalShown = builtIn && app.frame.sceneId === TERMINAL
  const startMenu = builtIn && !controlPanel && !terminalShown
  // The window a built-in scene opened over: its task button stays.
  const openWindow = builtIn ? app.state.openedOver : name
  const title = controlPanel ? 'Control Panel' : terminalShown ? 'Terminal' : startMenu ? 'Programs' : name
  const minimized = !builtIn && app.state.minimized === true
  const toggle = () => frameos.setState('minimized', !minimized)
  // A built-in scene's own command, again, goes back to the scene it opened over.
  const closeBuiltIn = () => frameos.dispatch(controlPanel ? 'sceneSettings' : terminalShown ? 'terminal' : 'sceneSwitcher')
  const taskWidth = Math.round(Math.min(160 * zoom, width * 0.34))
  return (
    <div className={`flex flex-col w-full h-full bg-[#008080] text-black text-[${px(16)}]`}>
      {minimized ? (
        <div className="flex-1" />
      ) : on(app.state.showWindowBar) ? (
        <Window
          title={title}
          icon={terminalShown ? <TerminalIcon /> : builtIn ? <Gear /> : <WindowIcon />}
          onSettings={builtIn ? undefined : () => frameos.dispatch('sceneSettings')}
          onMinimize={builtIn ? closeBuiltIn : toggle}
          onClose={builtIn ? closeBuiltIn : () => frameos.dispatch('sceneSwitcher')}
        >
          <yield />
        </Window>
      ) : (
        <yield />
      )}
      <Taskbar>
        <Toggle pressed={startMenu} className="shrink-0" onClick={() => frameos.dispatch('sceneSwitcher', { swap: true })}>
          <Logo />
          <span className="font-bold whitespace-nowrap">Start</span>
        </Toggle>
        {openWindow ? (
          <Toggle
            pressed={!builtIn && !minimized}
            className={`w-[${taskWidth}px] min-w-0`}
            onClick={builtIn ? closeBuiltIn : toggle}
          >
            <WindowIcon />
            <span className="flex-1 font-bold truncate">{openWindow}</span>
          </Toggle>
        ) : null}
        <Toggle pressed={controlPanel} className="shrink-0" onClick={() => frameos.dispatch('sceneSettings')}>
          <Gear />
          {roomy ? <span className="whitespace-nowrap">Control Panel</span> : null}
        </Toggle>
        <div className="flex-1" />
        <Tray app={app} now={now} />
      </Taskbar>
    </div>
  )
}

