// ---------------------------------------------------------------- the desktop
//
// What it keeps, in the layout's state (it goes along from scene to scene on a
// Pi, and is gone at a restart): `wins`, the windows open in the order they were
// opened, each {id, x, y, w, h, z, max, min, snap}, in the desktop's pixels (x to
// h is the window's own box, kept while it fills the desktop or is snapped to a
// half of it, `snap` 'l' or 'r'; a built-in scene's also its `title`); `boxes`,
// where each scene's window was when it closed, by scene id; `last`, the
// scene that had the focus at the last render; `asked`, the scene this layout last
// brought forward itself; `gone`, the scene whose window was just closed; `picked`,
// the desktop icon picked; `menu`, the Be menu open; `full`, `peek` and `drag`, a
// move or a size in progress.

const winsOf = (app) => (Array.isArray(app.state.wins) ? app.state.wins : [])
const topZ = (wins) => wins.reduce((z, w) => Math.max(z, w.z || 0), 0)

// What a window takes around its scene: the tab over the frame, and the frame's
// three bevels and its grey.
const chromeW = () => 6 * edge + 2 * Math.round(3 * zoom)
const chromeH = () => 8 * edge + 2 * Math.round(3 * zoom) + Math.round(22 * zoom)

function clamp(win, deskW, deskH) {
  const minW = Math.min(deskW, Math.round(160 * zoom))
  const minH = Math.min(deskH, Math.round(100 * zoom))
  win.w = Math.round(Math.max(minW, Math.min(win.w, deskW)))
  win.h = Math.round(Math.max(minH, Math.min(win.h, deskH)))
  // A tab stays where the pointer can get at it.
  const grip = Math.round(48 * zoom)
  win.x = Math.round(Math.max(grip - win.w, Math.min(win.x, deskW - grip)))
  win.y = Math.round(Math.max(0, Math.min(win.y, deskH - Math.round(24 * zoom))))
  return win
}

const boxesOf = (app) => (app.state.boxes && typeof app.state.boxes === 'object' ? app.state.boxes : {})

// A closed window's box, for when its scene opens again.
function keep(app, win) {
  const { x, y, w, h, max, snap } = win
  frameos.setState('boxes', { ...boxesOf(app), [win.id]: { x, y, w, h, max, snap } })
}

// The scene's own area in a new window, from the layout's "Window size" (`WxH`, in
// a desktop's pixels like every size here); null for the whole desktop.
function ownSize(app) {
  const m = /^(\d+)x(\d+)$/.exec(String(app.state.windowSize || '800x480'))
  return m ? { w: Math.round(Number(m[1]) * zoom), h: Math.round(Number(m[2]) * zoom) } : null
}

// A new window's box: `area` is where it should fit (the desktop beside the
// Deskbar), `desk` where it may go.
function placed(app, id, wins, area, desk) {
  const win = { id, z: topZ(wins) + 1 }
  // Where it was when it closed, if it was open before.
  const kept = boxesOf(app)[id]
  if (kept) return clamp({ ...kept, ...win }, desk.w, desk.h)
  // Otherwise the layout's size, its tab and frame around it, cascading from the
  // corner and all of it on the desktop.
  const step = Math.round(24 * zoom) * (wins.length % 6)
  const size = ownSize(app)
  const w = size ? size.w + chromeW() : area.w + 1
  const h = size ? size.h + chromeH() : area.h + 1
  if (w <= area.w && h <= area.h) {
    const x = Math.min(Math.round(16 * zoom) + step, area.w - w)
    const y = Math.min(Math.round(16 * zoom) + step, area.h - h)
    return clamp({ ...win, x, y, w, h, max: false }, desk.w, desk.h)
  }
  // Where it does not fit, the first window fills the desktop, which is what the
  // frame looked like before anything else was opened, and the next ones take
  // most of it; set to the whole desktop, every one fills it.
  const shown = wins.filter((other) => !other.min).length
  const box = { x: Math.round(16 * zoom) + step, y: Math.round(16 * zoom) + step, w: area.w * 0.62, h: area.h * 0.62 }
  return clamp({ ...win, ...box, max: !size || shown === 0 }, desk.w, desk.h)
}

// What another desktop had open when this layout was chosen in its place (its
// `openScenes`, handed over by the runtime: docs/scene-layouts.md "Windows"): a
// window each, cascading in that order, so the one that had the focus is on top.
function opened(app, names, titleOf, area, desk) {
  const wins = []
  for (const id of Array.isArray(app.state.openScenes) ? app.state.openScenes : []) {
    if (typeof id !== 'string' || wins.some((w) => w.id === id) || !(names[id] || isSystem(id))) continue
    const win = placed(app, id, wins, area, desk)
    if (isSystem(id)) win.title = titleOf(id, names)
    wins.push(win)
  }
  return wins
}

// What is open, the one with the focus last: what a layout chosen in this one's
// place opens (`openScenes`).
function keepOpen(app, wins, current) {
  const order = wins
    .filter((w) => w.id !== current)
    .sort((a, b) => (a.z || 0) - (b.z || 0))
    .map((w) => w.id)
  if (wins.some((w) => w.id === current)) order.push(current)
  if (JSON.stringify(order) !== JSON.stringify(app.state.openScenes || [])) frameos.setState('openScenes', order)
}

// Where a window is drawn: its own box, the whole of `area`, or a half of it.
function boxOf(win, area) {
  const half = Math.round(area.w / 2)
  if (win.max) return { x: 0, y: 0, w: area.w, h: area.h }
  if (win.snap === 'l') return { x: 0, y: 0, w: half, h: area.h }
  if (win.snap === 'r') return { x: half, y: 0, w: area.w - half, h: area.h }
  return { x: win.x, y: win.y, w: win.w, h: win.h }
}

// What a press, a key or the Be menu does to the windows. Each one reads the state
// afresh: a drag's moves come faster than renders.
function actions(app) {
  const current = app.frame.sceneId
  const update = (id, change) => {
    const next = winsOf(app).map((w) => (w.id === id ? { ...w, ...change(w) } : w))
    frameos.setState('wins', next)
  }
  // Every window this layout brings forward goes through here, so a built-in
  // scene that loses the focus some other way is known to have gone back.
  const go = (id) => {
    frameos.setState('asked', id)
    frameos.dispatch('setCurrentScene', { sceneId: id })
  }
  const focus = (id) => {
    frameos.setState('menu', false)
    update(id, () => ({ min: false }))
    if (id !== current) go(id)
  }
  const open = (id) => {
    frameos.setState('menu', false)
    if (winsOf(app).some((w) => w.id === id)) return focus(id)
    if (id !== current) go(id)
    else if (app.state.gone === id) frameos.setState('gone', null)
  }
  // Read when a handler runs, not when it was drawn: a press before it may have
  // brought another window forward.
  const showing = () => app.frame.sceneId
  const windowOf = (id) => winsOf(app).find((w) => w.id === id)
  // A built-in scene opens over a scene. Over another built-in one, that one stays
  // open in its window, and the scene window on top comes forward to open it over;
  // with none, the built-in one goes back where it came from. Either way the
  // focus is this layout's doing (`asked`): the one left open keeps its window.
  const overAScene = () => {
    const now = showing()
    if (!isSystem(now)) return
    const top = winsOf(app)
      .filter((w) => !isSystem(w.id) && !w.min)
      .sort((a, b) => (b.z || 0) - (a.z || 0))[0]
    if (top) go(top.id)
    else frameos.dispatch(commandOf(now))
  }
  // A scene's settings, from the gear box on its tab: a window of their own,
  // opened over the scene's window brought forward first; open already, that
  // window comes forward as it was left.
  const sceneSettings = (id) => {
    frameos.setState('menu', false)
    if (windowOf(settingsOf(id))) return focus(settingsOf(id))
    if (id !== showing()) go(id)
    frameos.dispatch('sceneSettings', {})
    frameos.setState('asked', settingsOf(id))
  }
  // A built-in scene of the frame's, one window each: Preferences (the frame's
  // page: the Be menu, the tray, the disk icon), Scenes and Terminal. Open
  // already, it comes forward as it was left.
  const builtIn = (id, command, payload) => () => {
    frameos.setState('menu', false)
    if (windowOf(id)) return focus(id)
    overAScene()
    frameos.dispatch(command, payload)
    frameos.setState('asked', id)
  }
  const controlPanel = builtIn(SETTINGS, 'sceneSettings', { page: 'frame' })
  const sceneList = builtIn(SWITCHER, 'sceneSwitcher', {})
  const terminal = builtIn(TERMINAL, 'terminal', {})
  // The window in front went away: the next one down takes the focus.
  const nextAfter = (id) =>
    winsOf(app)
      .filter((w) => w.id !== id && !w.min)
      .sort((a, b) => (b.z || 0) - (a.z || 0))[0]
  const minimize = (id) => {
    update(id, () => ({ min: true }))
    const next = id === current ? nextAfter(id) : null
    if (next) go(next.id)
  }
  // A built-in scene with the focus closes as its own Cancel does, back to the
  // scene it was opened over.
  const close = (id) => {
    const next = id === current ? nextAfter(id) : null
    const win = winsOf(app).find((w) => w.id === id)
    if (win) keep(app, win)
    frameos.setState('wins', winsOf(app).filter((w) => w.id !== id))
    if (id !== current) return
    frameos.setState('gone', id)
    frameos.setState('full', false)
    if (isSystem(id)) frameos.dispatch(commandOf(id))
    else if (next) go(next.id)
  }
  const toggleMax = (id) => update(id, (w) => ({ max: !w.max, snap: null }))
  const toggleFull = () => {
    frameos.setState('menu', false)
    frameos.setState('peek', false)
    frameos.setState('full', !on(app.state.full))
  }
  // Alt+Tab: the window that had the focus before this one, so twice comes back;
  // with Shift, the one at the bottom, so every window comes round in turn.
  const cycle = (back) => {
    const others = winsOf(app)
      .filter((w) => w.id !== current)
      .sort((a, b) => (b.z || 0) - (a.z || 0))
    const next = back ? others[others.length - 1] : others[0]
    if (next) focus(next.id)
    return !!next
  }
  return { update, focus, open, sceneSettings, controlPanel, sceneList, terminal, minimize, close, toggleMax, toggleFull, cycle }
}

// What a built-in scene's window is called before it has shown its page here.
const titleOf = (id, names) => {
  const scene = settingsFor(id)
  if (scene) return `${names[scene] || scene} Settings`
  return id === SWITCHER ? 'Scenes' : id === TERMINAL ? 'Terminal' : 'Preferences'
}

// What a built-in scene's window is called, by the page it shows.
function systemTitle(app, names) {
  const scene = settingsFor(app.frame.sceneId)
  if (scene) return `${names[scene] || app.state.openedOver || scene} Settings`
  if (app.frame.sceneId === SWITCHER) return 'Scenes'
  if (app.frame.sceneId === TERMINAL) return 'Terminal'
  const page = app.frame.sceneName
  if (page === 'Frame settings') return 'Preferences'
  if (page === 'Layout settings') return 'Appearance'
  return app.state.openedOver ? `${app.state.openedOver} Settings` : 'Settings'
}

function desktop(app, now, width, height, corner) {
  const scale = app.frame.scale || 1
  const builtIn = app.frame.systemScene === true
  const current = app.frame.sceneId
  const names = {}
  for (const scene of app.frame.scenes) names[scene.id] = scene.name || scene.id
  if (!builtIn && current && !names[current]) names[current] = app.frame.sceneName || current
  const store = storeOf(app)
  const assets = assetsOf(app)
  storeId = store ? store.id : null
  assetsId = assets ? assets.id : null
  const frameApps = [store, assets].filter(Boolean)
  const programs = app.frame.scenes.filter((scene) => !isFrameApp(scene))
  // The Deskbar stands in the top right corner, over the desktop, and a window
  // filling the desktop leaves its column; on a narrow panel it runs along the top
  // and the desktop is under it.
  const barW = Math.round(156 * zoom)
  const barH = corner ? 0 : Math.round(28 * zoom) + 3 * edge
  const desk = { x: 0, y: barH, w: width, h: Math.max(1, height - barH) }
  const area = { w: corner ? Math.max(1, width - barW) : desk.w, h: desk.h }

  // Whatever brought a scene forward (a window, the Deskbar, the Be menu, an icon,
  // a button, the API), its window is open and on top, and the one it took the
  // focus from is next below it. A built-in scene's window is named by what it
  // shows while it has the focus, and closes once it has gone back by itself: the
  // focus left it for a scene, and not because this layout moved it. One that
  // opened another (the gear in a scene's settings opening Preferences) did not
  // go back, and stays open.
  // A layout just chosen in another desktop's place has no windows of its own yet:
  // it opens what that one had open.
  const fresh = !Array.isArray(app.state.wins)
  const saved = fresh ? opened(app, names, titleOf, area, desk) : winsOf(app)
  const wins = saved.filter((w) => w && (names[w.id] || isSystem(w.id)))
  let changed = fresh ? wins.length > 0 : wins.length !== saved.length
  if (current) {
    let win = wins.find((w) => w.id === current)
    if (!win && app.state.gone !== current) {
      win = placed(app, current, wins, area, desk)
      wins.push(win)
      changed = true
    }
    if (win && builtIn && win.title !== systemTitle(app, names)) {
      win.title = systemTitle(app, names)
      changed = true
    }
    if (app.state.last !== current) {
      if (win && win.min) win.min = false
      const before = wins.find((w) => w.id === app.state.last)
      if (before && isSystem(before.id) && !isSystem(current) && app.state.asked !== current) {
        keep(app, before)
        wins.splice(wins.indexOf(before), 1)
      } else if (before) before.z = topZ(wins) + 1
      if (app.state.gone && app.state.gone !== current) frameos.setState('gone', null)
      if (app.state.asked) frameos.setState('asked', null)
      frameos.setState('last', current)
      changed = true
    }
  }
  if (changed) frameos.setState('wins', wins)
  keepOpen(app, wins, current)
  for (const win of wins) if (isSystem(win.id)) names[win.id] = win.title || titleOf(win.id, names)

  const focused = wins.find((w) => w.id === current && !w.min)
  const full = !!focused && on(app.state.full)
  const menu = on(app.state.menu)
  // How far down the Deskbar reaches: the gem, the tray and a row a window.
  const deskbarH = corner ? Math.round(56 * zoom) + 7 * edge + wins.length * (Math.round(24 * zoom) + 2 * edge) : barH
  const { update, focus, open, sceneSettings, controlPanel, sceneList, terminal, minimize, close, toggleMax, toggleFull } =
    actions(app)

  // A press on a tab moves the window, one on its frame sizes it from that edge;
  // the moves that follow are captured by what was pressed. Let go at the top of
  // the desktop, a moved window fills it, at the left or right edge it takes that
  // half; dragged away again, it has its own size back.
  const startDrag = (drawn, mode) => (e) => {
    frameos.setState('picked', null)
    // As it is now, not as it was drawn: a size may have come since.
    const win = winsOf(app).find((w) => w.id === drawn.id) || drawn
    const box = boxOf(win, area)
    const docked = !!(win.max || win.snap)
    // A half sized from its edge is a window of that size from then on.
    if (docked && mode !== 'move') update(win.id, () => ({ ...box, snap: null }))
    frameos.setState('drag', {
      id: win.id,
      mode,
      x: e.x,
      y: e.y,
      from: box,
      own: { w: win.w, h: win.h },
      docked: docked && mode === 'move',
      at: null,
    })
    if (win.id !== current) focus(win.id)
  }
  const dragTo = (e) => {
    const drag = app.state.drag
    if (!drag || !e.buttons) return
    const dx = (e.x - drag.x) / scale
    const dy = (e.y - drag.y) / scale
    if (drag.mode === 'move') {
      const x = e.x / scale
      const y = e.y / scale - desk.y
      const at = y <= 2 ? 'max' : x <= 2 ? 'l' : x >= desk.w - 3 ? 'r' : null
      if (drag.docked) {
        // A press that does not move leaves it be.
        if (Math.abs(dx) + Math.abs(dy) < 8 * zoom) return
        // Its own size, with the pointer as far across the tab as it was.
        const across = Math.min(1, (drag.x / scale - drag.from.x) / drag.own.w)
        const from = { x: drag.x / scale - across * drag.own.w, y: drag.from.y, w: drag.own.w, h: drag.own.h }
        frameos.setState('drag', { ...drag, at, docked: false, from })
        update(drag.id, () => ({ ...clamp({ ...from, x: from.x + dx, y: from.y + dy }, desk.w, desk.h), max: false, snap: null }))
        return
      }
      if (at !== drag.at) frameos.setState('drag', { ...drag, at })
    }
    const f = drag.from
    update(drag.id, () => {
      const box = { ...f }
      if (drag.mode === 'move') {
        box.x = f.x + dx
        box.y = f.y + dy
      } else {
        if (drag.mode.includes('l')) {
          box.x = Math.min(f.x + dx, f.x + f.w - 80 * zoom)
          box.w = f.w - (box.x - f.x)
        }
        if (drag.mode.includes('r')) box.w = f.w + dx
        if (drag.mode.includes('t')) {
          box.y = Math.max(0, Math.min(f.y + dy, f.y + f.h - 60 * zoom))
          box.h = f.h - (box.y - f.y)
        }
        if (drag.mode.includes('b')) box.h = f.h + dy
      }
      return clamp(box, desk.w, desk.h)
    })
  }
  const endDrag = () => {
    const drag = app.state.drag
    frameos.setState('drag', null)
    if (drag && drag.mode === 'move' && drag.at && !drag.docked) {
      update(drag.id, () => (drag.at === 'max' ? { max: true, snap: null } : { max: false, snap: drag.at }))
    }
  }
  const corner14 = 14 * zoom
  const edgeOf = (e) => {
    const x = e.localX < corner14 ? 'l' : e.localX > e.width - corner14 ? 'r' : ''
    const y = e.localY < corner14 ? 't' : e.localY > e.height - corner14 ? 'b' : ''
    return y + x || 'b'
  }
  const sizing = (win) => ({
    onPointerDown: (e) => startDrag(win, edgeOf(e))(e),
    onPointerMove: dragTo,
    onPointerUp: endDrag,
  })
  // A double click on the tab puts the window away, as it did.
  const moving = (win) => ({
    onPointerDown: startDrag(win, 'move'),
    onPointerMove: dragTo,
    onPointerUp: endDrag,
    onDoubleClick: () => minimize(win.id),
  })

  // Only the tab and the frame take the pointer: beside the tab, a press goes to
  // what is behind it.
  const windowOf = (win) => {
    const active = win.id === current
    const box = boxOf(win, area)
    return (
      <div className={`absolute left-[${box.x}px] top-[${box.y}px] w-[${box.w}px] h-[${box.h}px] flex flex-col`}>
        <Tab
          title={names[win.id]}
          active={active}
          onClose={() => close(win.id)}
          onSettings={isSystem(win.id) ? undefined : () => sceneSettings(win.id)}
          onZoom={() => toggleMax(win.id)}
          drag={moving(win)}
        />
        <Frame frame={win.max ? {} : sizing(win)}>
          <div className="relative flex flex-col flex-1 min-h-0">
            {active ? <yield /> : <Scene id={win.id} />}
            {/* A press on a window behind brings it forward, and is only that. */}
            {active ? null : <div className="absolute inset-0" onPointerDown={() => focus(win.id)} />}
          </div>
        </Frame>
      </div>
    )
  }

  // Where a window let go now would go: its outline, four bars, over the windows.
  const outline = () => {
    const drag = app.state.drag
    if (!drag || drag.mode !== 'move' || !drag.at || drag.docked) return null
    const b = boxOf({ max: drag.at === 'max', snap: drag.at }, area)
    const w = Math.max(2, Math.round(3 * zoom))
    const bar = (x, y, bw, bh) => <div className={`absolute left-[${x}px] top-[${y}px] w-[${bw}px] h-[${bh}px] bg-[${c.tab}]`} />
    return [bar(b.x, b.y, b.w, w), bar(b.x, b.y + b.h - w, b.w, w), bar(b.x, b.y, w, b.h), bar(b.x + b.w - w, b.y, w, b.h)]
  }

  // Tracker's icons, in the corner's column under the Deskbar and on leftwards
  // where they do not fit: the frame's disk (Preferences), then the scenes. A click
  // picks one, a double click opens it. They stay where they are when a window
  // opens: under room for three of the Deskbar's rows, which a fourth covers.
  const icons = () => {
    if (!corner || !on(app.state.showIcons)) return null
    const top = Math.round((56 + 3 * 24 + 14) * zoom) + 13 * edge
    const slot = Math.round(66 * zoom)
    const iconW = Math.round(88 * zoom)
    const perColumn = Math.max(1, Math.floor((height - top) / slot))
    // The frame's own apps, not its scenes (the Be menu has those): its disk (the
    // frame's settings), the scene list, the store and the asset browser where the
    // frame has them, and the terminal.
    const items = [
      { id: SETTINGS, label: 'Frame', icon: <DiskIcon />, go: controlPanel },
      { id: SWITCHER, label: 'Scenes', icon: <FolderIcon />, go: sceneList },
      ...frameApps.map((scene) => ({
        id: scene.id,
        label: names[scene.id],
        icon: scene.id === storeId ? <StoreGlyph size={34} /> : <FolderIcon>
            <Picture />
          </FolderIcon>,
        go: () => open(scene.id),
      })),
      { id: TERMINAL, label: 'Terminal', icon: <TerminalGlyph size={34} />, go: terminal },
    ]
    return items.map((item, i) => {
      const x = Math.round(width - barW + (barW - iconW) / 2 - Math.floor(i / perColumn) * (iconW + 4 * zoom))
      const y = top + (i % perColumn) * slot
      return (
        <DesktopIcon
          label={item.label}
          picked={app.state.picked === item.id}
          className={`absolute left-[${x}px] top-[${y}px]`}
          onClick={() => frameos.setState('picked', item.id)}
          onDoubleClick={() => (frameos.setState('picked', null), item.go())}
        >
          {item.icon}
        </DesktopIcon>
      )
    })
  }

  // The Deskbar: the gem (the Be menu), the tray (Preferences) and the windows
  // open, the one in front pressed in and the ones put away dimmed.
  const teams = () =>
    wins.map((win) => {
      const front = win.id === current && !win.min
      return (
        <Team
          pressed={front}
          dim={win.min}
          label={names[win.id]}
          className={corner ? '' : 'min-w-0 shrink'}
          onClick={() => (front ? minimize(win.id) : focus(win.id))}
        >
          {glyphOf(win.id)}
        </Team>
      )
    })
  const gem = (className, inner) => (
    <Bevel pressed={menu} className={className} inner={inner} onClick={() => frameos.setState('menu', !menu)}>
      <Gem />
    </Bevel>
  )
  const deskbar = () =>
    corner ? (
      <div className={`absolute right-0 top-0 w-[${barW}px] flex flex-col border-l-${edge} border-b-${edge} border-[${c.line}]`}>
        {gem('', `items-center justify-center h-[${px(32)}]`)}
        <Tray app={app} now={now} onClick={controlPanel} />
        {teams()}
      </div>
    ) : (
      <div className={`absolute left-0 top-0 w-full h-[${barH}px] flex items-stretch border-b-${edge} border-[${c.line}] bg-[${c.panel}]`}>
        {gem('shrink-0', `items-center justify-center w-[${px(46)}]`)}
        <div className="flex flex-1 min-w-0">{teams()}</div>
        <Tray app={app} now={now} className="shrink-0" onClick={controlPanel} />
      </div>
    )

  // The Be menu, beside the Deskbar in the corner, under the gem along the top.
  const beMenu = () => {
    const Item = ({ onClick, children }) => (
      <div className={`flex items-center gap-[${px(6)}] h-[${px(24)}] px-[${px(8)}] whitespace-nowrap ${c.pick}`} onClick={onClick}>
        {children}
      </div>
    )
    const Rule = () => (
      <div className={`flex flex-col shrink-0 py-[${px(3)}]`}>
        <div className={`h-[${edge}px] bg-[${c.shade}]`} />
        <div className={`h-[${edge}px] bg-[${c.light}]`} />
      </div>
    )
    const menuW = Math.round(Math.min(width - 8 * zoom, 210 * zoom))
    const place = corner ? `right-[${barW}px] top-0` : `left-0 top-[${barH}px]`
    // The menu takes a press itself: the cover under it closes the menu on a press,
    // and a render before the release would take the item away from the click.
    return (
      <div
        className={`absolute ${place} w-[${menuW}px] max-h-[${desk.h}px] flex flex-col py-[${px(2)}] overflow-y-auto border-[${edge}px] border-[${c.line}] bg-[${c.panel}]`}
        onPointerDown={() => {}}
      >
        {programs.map((scene) => (
          <Item onClick={() => open(scene.id)}>
            <SceneGlyph />
            <span className="flex-1 truncate">{names[scene.id]}</span>
          </Item>
        ))}
        <Rule />
        {frameApps.map((scene) => (
          <Item onClick={() => open(scene.id)}>
            {glyphOf(scene.id)}
            <span className="flex-1 truncate">{names[scene.id]}</span>
          </Item>
        ))}
        <Item onClick={controlPanel}>
          <SettingsGlyph />
          <span className="flex-1 truncate">Preferences</span>
        </Item>
        <Item onClick={sceneList}>
          <SceneGlyph />
          <span className="flex-1 truncate">Scenes</span>
        </Item>
        <Item onClick={terminal}>
          <TerminalGlyph />
          <span className="flex-1 truncate">Terminal</span>
        </Item>
        {focused ? <Rule /> : null}
        {focused ? (
          <Item onClick={toggleFull}>
            <SceneGlyph />
            <span className="flex-1 truncate">Full screen</span>
          </Item>
        ) : null}
      </div>
    )
  }

  const cover = menu ? (
    <div className="absolute inset-0" onPointerDown={() => frameos.setState('menu', false)} onClick={() => {}} />
  ) : null

  if (full) {
    // The panel is the window's. The pointer at the top edge brings the Deskbar;
    // moved back over the window, it goes again, unless the Be menu is open.
    const peek = on(app.state.peek) || menu
    return (
      <div className={`relative w-full h-full ${c.desk} text-black text-[${px(13)}]`}>
        <div className="absolute inset-0 flex flex-col">
          <yield />
        </div>
        {!peek ? (
          <div className="absolute left-0 top-0 w-full h-[2px]" onPointerMove={() => frameos.setState('peek', true)} />
        ) : menu ? null : (
          <div
            className={`absolute left-0 top-[${deskbarH + Math.round(16 * zoom)}px] w-full h-[${Math.max(1, height - deskbarH - Math.round(16 * zoom))}px]`}
            onPointerMove={() => frameos.setState('peek', false)}
          />
        )}
        {cover}
        {menu ? beMenu() : null}
        {peek ? deskbar() : null}
      </div>
    )
  }

  const shown = wins.filter((w) => !w.min && !(focused && w.id === focused.id)).sort((a, b) => (a.z || 0) - (b.z || 0))
  if (focused) shown.push(focused)
  return (
    <div className={`relative w-full h-full ${c.desk} text-black text-[${px(13)}]`}>
      <div
        className={`absolute left-0 top-[${desk.y}px] w-[${desk.w}px] h-[${desk.h}px]`}
        onClick={() => frameos.setState('picked', null)}
      >
        {icons()}
        {shown.map(windowOf)}
        {outline()}
      </div>
      {cover}
      {menu ? beMenu() : null}
      {deskbar()}
    </div>
  )
}

// F11 gives the panel to the window in front and takes it back; Escape closes the
// Be menu and leaves the full screen; Alt+Tab brings the window before forward
// (Shift: the one at the bottom), Alt+W (or Alt+F4) closes the one in front. The
// scene heard the key first.
export function onEvent(app, context) {
  if (context.event !== 'keyDown' || !Array.isArray(app.frame.scenes) || !windowsOn(app)) return false
  const payload = context.payload || {}
  const key = payload.key
  if (key === 'F11') {
    frameos.setState('peek', false)
    frameos.setState('full', !on(app.state.full))
    return true
  }
  if (key === 'Escape' && (on(app.state.menu) || on(app.state.full))) {
    frameos.setState('menu', false)
    frameos.setState('full', false)
    return true
  }
  const alt = payload.alt === true
  if (key === 'Tab' && alt) return actions(app).cycle(payload.shift === true)
  if (alt && (key === 'F4' || key === 'w' || key === 'W') && app.frame.sceneId) {
    actions(app).close(app.frame.sceneId)
    return true
  }
  return false
}

const windowsOn = (app) => app.state.windows !== false && app.state.windows !== 'false'

export function get(app) {
  // app.frame's size is the panel's over the render scale, before the frame's rotation.
  const turned = (app.frame.rotate || 0) % 180 !== 0
  const width = turned ? app.frame.height : app.frame.width
  const height = turned ? app.frame.width : app.frame.height
  const shortSide = Math.min(app.frame.width, app.frame.height)
  zoom = shortSide >= (app.frame.paper ? 1000 : 2160) ? 2 : shortSide >= 480 ? 1 : shortSide / 480
  edge = Math.max(1, Math.round(zoom))
  c = app.frame.color === false ? MONO : app.frame.paper ? PAPER : R5
  dress(app, THEMES, 'beos')
  // The Deskbar stands in the corner where there is room beside the window, and
  // runs along the top where there is not; the icons need the corner's column.
  const corner = width >= 600 * Math.max(zoom, 1)
  const now = new Date()
  // The clock changes on the minute: nothing to draw until then.
  frameos.setNextSleep(60 - now.getSeconds())
  if (Array.isArray(app.frame.scenes) && windowsOn(app)) return desktop(app, now, width, height, corner)
  // One scene at a time: nothing else is open, nothing for another layout to open.
  if (Array.isArray(app.state.openScenes) && app.state.openScenes.length) frameos.setState('openScenes', [])
  const name = app.frame.sceneName || 'FrameOS'
  const builtIn = app.frame.systemScene === true
  // The terminal (not on an ESP32, where app.frame.sceneId is not there either).
  const terminalOpen = builtIn && app.frame.sceneId === TERMINAL
  const settingsOpen = builtIn && !terminalOpen && name.includes('settings')
  const listOpen = builtIn && !settingsOpen && !terminalOpen
  // The scene a built-in one opened over keeps its place in the Deskbar.
  const scene = builtIn ? app.state.openedOver || '' : name
  const title = terminalOpen
    ? 'Terminal'
    : listOpen
    ? 'Scenes'
    : settingsOpen
    ? name.startsWith('Frame')
      ? 'Preferences'
      : 'Settings'
    : name
  const hidden = !builtIn && app.state.hidden === true
  const zoomed = app.state.zoomed === true
  const framed = on(app.state.showWindow)
  // A built-in scene's own command, again, goes back to the scene it opened over.
  const closeBuiltIn = () => frameos.dispatch(terminalOpen ? 'terminal' : settingsOpen ? 'sceneSettings' : 'sceneSwitcher')
  const openList = () => frameos.dispatch('sceneSwitcher', { swap: true })
  const openSettings = () => frameos.dispatch('sceneSettings')
  const openFrame = () => frameos.dispatch('sceneSettings', { page: 'frame' })
  const showScene = builtIn ? closeBuiltIn : () => frameos.setState('hidden', !hidden)
  const content = hidden ? (
    <div className="flex-1" />
  ) : framed ? (
    <div className={`flex flex-col flex-1 min-w-0 min-h-0 ${zoomed ? '' : `p-[${px(12)}]`}`}>
      <Window
        title={title}
        onClose={builtIn ? closeBuiltIn : () => frameos.dispatch('sceneSwitcher')}
        onZoom={() => frameos.setState('zoomed', !zoomed)}
        onHide={builtIn ? closeBuiltIn : () => frameos.setState('hidden', true)}
      >
        <yield />
      </Window>
    </div>
  ) : (
    <yield />
  )
  const sceneTeam = scene ? (
    <Team pressed={false} dim={hidden} label={scene} onClick={showScene} className={corner ? '' : 'min-w-0 shrink'}>
      <SceneGlyph />
    </Team>
  ) : null
  const settingsTeam = (
    <Team pressed={settingsOpen} label="Settings" onClick={openSettings} className="shrink-0">
      <SettingsGlyph />
    </Team>
  )
  if (!corner) {
    return (
      <div className={`flex flex-col w-full h-full ${c.desk} text-black text-[${px(13)}]`}>
        <div className={`flex items-stretch shrink-0 border-b-${edge} border-[${c.line}]`}>
          <Bevel pressed={listOpen} className="shrink-0" inner={`items-center justify-center w-[${px(46)}] h-[${px(28)}]`} onClick={openList}>
            <Gem />
          </Bevel>
          {sceneTeam}
          {settingsTeam}
          <div className={`flex-1 bg-[${c.panel}]`} />
          <Tray app={app} now={now} className="shrink-0" onClick={openFrame} />
        </div>
        {content}
      </div>
    )
  }
  return (
    <div className={`flex w-full h-full ${c.desk} text-black text-[${px(13)}]`}>
      {content}
      <div className={`flex flex-col items-center shrink-0 w-[${px(156)}]`}>
        <div className={`flex flex-col self-stretch border-l-${edge} border-b-${edge} border-[${c.line}]`}>
          <Bevel pressed={listOpen} inner={`items-center justify-center h-[${px(32)}]`} onClick={openList}>
            <Gem />
          </Bevel>
          <Tray app={app} now={now} onClick={openFrame} />
          {sceneTeam}
          {settingsTeam}
        </div>
        {on(app.state.showIcons) ? (
          <div className={`flex flex-col items-center gap-[${px(8)}] pt-[${px(14)}]`}>
            <DesktopIcon label="Frame" onClick={openFrame}>
              <DiskIcon />
            </DesktopIcon>
            <DesktopIcon label="Scenes" onClick={openList}>
              <FolderIcon />
            </DesktopIcon>
            <DesktopIcon label="Settings" onClick={openSettings}>
              <FolderIcon>
                <path d={GEAR} fill="#a8a8a8" stroke="#202020" strokeWidth="0.8" transform="translate(9.5 3.5) scale(0.8)" />
              </FolderIcon>
            </DesktopIcon>
          </div>
        ) : null}
      </div>
    </div>
  )
}
